class Hotel:
    def __init__(self, name, rooms):
        self._name = name
        self._available_rooms = rooms.copy() if isinstance(rooms, dict) else {}
        self._booked_rooms = {}

    @property
    def name(self):
        return self._name

    @property
    def available_rooms(self):
        return self._available_rooms.copy()

    @property
    def booked_rooms(self):
        return self._booked_rooms

    def _is_room_type_available(self, room_type):
        return room_type in self._available_rooms

    def _calculate_available_room_count(self, room_type):
        if not self._is_room_type_available(room_type):
            return 0
        return self._available_rooms[room_type]

    def _ensure_room_type_in_booked_rooms(self, room_type):
        if room_type not in self._booked_rooms:
            self._booked_rooms[room_type] = {}

    def _can_book_room(self, room_type, room_number):
        return self._calculate_available_room_count(room_type) >= room_number

    def _process_successful_booking(self, room_type, room_number, name):
        self._ensure_room_type_in_booked_rooms(room_type)
        self._booked_rooms[room_type][name] = room_number
        self._available_rooms[room_type] -= room_number
        return "Success!"

    def _get_partial_available_count(self, room_type):
        available = self._calculate_available_room_count(room_type)
        return available if available != 0 else False

    def book_room(self, room_type, room_number, name):
        if not self._is_room_type_available(room_type):
            return False
        if self._can_book_room(room_type, room_number):
            return self._process_successful_booking(room_type, room_number, name)
        return self._get_partial_available_count(room_type)

    def _is_guest_booked_for_room_type(self, room_type, name):
        return room_type in self._booked_rooms and name in self._booked_rooms[room_type]

    def _get_booked_room_number(self, room_type, name):
        if self._is_guest_booked_for_room_type(room_type, name):
            return self._booked_rooms[room_type][name]
        return None

    def _can_check_in_room(self, room_type, room_number, name):
        booked = self._get_booked_room_number(room_type, name)
        return booked is not None and room_number <= booked

    def _process_check_in(self, room_type, room_number, name):
        self._booked_rooms[room_type].pop(name, None)

    def _process_partial_check_in(self, room_type, room_number, name):
        self._booked_rooms[room_type][name] -= room_number

    def check_in(self, room_type, room_number, name):
        if not self._is_room_type_available(room_type) and room_type not in self._booked_rooms:
            return False
        if self._is_guest_booked_for_room_type(room_type, name):
            if self._can_check_in_room(room_type, room_number, name):
                if room_number == self._get_booked_room_number(room_type, name):
                    self._process_check_in(room_type, room_number, name)
                else:
                    self._process_partial_check_in(room_type, room_number, name)
            else:
                return False

    def _add_rooms_to_available(self, room_type, room_number):
        if room_type in self._available_rooms:
            self._available_rooms[room_type] += room_number
        else:
            self._available_rooms[room_type] = room_number

    def check_out(self, room_type, room_number):
        self._add_rooms_to_available(room_type, room_number)

    def get_available_rooms(self, room_type):
        return self._available_rooms.get(room_type, 0)
